"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type KeyboardEvent,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** One choice in a dropdown. */
export interface DropdownOption<T extends string> {
  value: T;
  /** Plain text, because type-ahead matches against it. */
  label: string;
  /** A small glyph before the label. Give each option its own shape so the choice never rests on colour. */
  icon?: ReactNode;
  disabled?: boolean;
}

/** Props for a dropdown. Pass `value` to control it, or `defaultValue` to let it hold its own state. */
export type DropdownProps<T extends string> = Omit<
  ComponentPropsWithoutRef<"div">,
  "onChange" | "children" | "defaultValue"
> & {
  options: DropdownOption<T>[];
  value?: T;
  defaultValue?: T;
  onValueChange?: (value: T) => void;
  /** Shown on the trigger while nothing is chosen. */
  placeholder?: string;
  disabled?: boolean;
};

// A menu is opened often, so it arrives fast and leaves faster.
const OPEN: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };
const CLOSE: Transition = { duration: 0.12, ease: [0.165, 0.84, 0.44, 1] };
const OPTION_STAGGER = 0.02;
const TYPE_AHEAD_MS = 500;

/**
 * Picks one option from a list that grows out of its trigger. Focus stays on
 * the trigger the whole time, so closing never has to send it back.
 */
export function Dropdown<T extends string>({
  options,
  value,
  defaultValue,
  onValueChange,
  placeholder = "Choose an option",
  disabled,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...rootProps
}: DropdownProps<T>) {
  const [ownValue, setOwnValue] = useState<T | undefined>(defaultValue);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const selected = value ?? ownValue;
  const selectedIndex = options.findIndex((option) => option.value === selected);
  const reduceMotion = useReducedMotion();
  const id = useId();
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const typed = useRef({ text: "", timer: 0 });

  const optionId = (index: number) => `${id}-option-${index}`;
  const enabled = options.flatMap((option, index) => (option.disabled ? [] : [index]));

  useEffect(() => {
    if (!open) return;
    const closeOnOutsidePress = (event: PointerEvent) => {
      if (event.target instanceof Node && !root.current?.contains(event.target)) setOpen(false);
    };
    document.addEventListener("pointerdown", closeOnOutsidePress);
    return () => document.removeEventListener("pointerdown", closeOnOutsidePress);
  }, [open]);

  useEffect(() => {
    if (open && active >= 0) document.getElementById(`${id}-option-${active}`)?.scrollIntoView?.({ block: "nearest" });
  }, [open, active, id]);

  useEffect(() => {
    const pending = typed.current;
    return () => window.clearTimeout(pending.timer);
  }, []);

  const openAt = (index: number) => {
    setActive(index);
    setOpen(true);
  };

  const choose = (index: number) => {
    const option = options[index];
    if (!option || option.disabled) return;
    if (value === undefined) setOwnValue(option.value);
    onValueChange?.(option.value);
    setOpen(false);
    trigger.current?.focus();
  };

  const step = (delta: 1 | -1) => {
    const position = enabled.indexOf(active);
    // From no active option, a forward step lands on the first and a backward step on the last.
    const next = position === -1 ? (delta > 0 ? 0 : enabled.length - 1) : position + delta;
    const index = enabled[Math.min(Math.max(next, 0), enabled.length - 1)];
    if (index !== undefined) openAt(index);
  };

  const typeAhead = (character: string) => {
    const pending = typed.current;
    window.clearTimeout(pending.timer);
    pending.text += character.toLowerCase();
    pending.timer = window.setTimeout(() => {
      pending.text = "";
    }, TYPE_AHEAD_MS);
    // A single letter pressed again moves on to the next match; a longer string keeps refining the current one.
    const from = enabled.indexOf(active) + (pending.text.length === 1 ? 1 : 0);
    const order = [...enabled.slice(Math.max(from, 0)), ...enabled.slice(0, Math.max(from, 0))];
    const match = order.find((index) => options[index]?.label.toLowerCase().startsWith(pending.text));
    if (match !== undefined) openAt(match);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const { key } = event;
    if (key === "Escape" || key === "Tab") {
      if (open && key === "Escape") event.preventDefault();
      setOpen(false);
      return;
    }
    if (key === "Enter" || key === " ") {
      event.preventDefault();
      if (open) choose(active);
      else openAt(selectedIndex >= 0 ? selectedIndex : (enabled[0] ?? -1));
    } else if (key === "ArrowDown" || key === "ArrowUp") {
      event.preventDefault();
      if (open) step(key === "ArrowDown" ? 1 : -1);
      else openAt(selectedIndex >= 0 ? selectedIndex : (enabled[key === "ArrowDown" ? 0 : enabled.length - 1] ?? -1));
    } else if (key === "Home" || key === "End") {
      event.preventDefault();
      openAt(enabled[key === "Home" ? 0 : enabled.length - 1] ?? -1);
    } else if (key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) {
      event.preventDefault();
      typeAhead(key);
    }
  };

  const current = options[selectedIndex];

  return (
    <div {...rootProps} ref={root} className={cn("relative inline-block w-56 text-sm", className)}>
      <button
        ref={trigger}
        type="button"
        role="combobox"
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`${id}-list`}
        aria-activedescendant={open && active >= 0 ? optionId(active) : undefined}
        disabled={disabled}
        onClick={() => (open ? setOpen(false) : openAt(selectedIndex >= 0 ? selectedIndex : (enabled[0] ?? -1)))}
        onKeyDown={handleKeyDown}
        onBlur={() => setOpen(false)}
        className={cn(
          "flex min-h-11 w-full cursor-pointer touch-manipulation items-center gap-2 rounded-lg border border-border bg-background px-3 text-left text-foreground outline-none",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-50",
        )}
      >
        {current?.icon}
        <span className={cn("min-w-0 flex-1 truncate", current ? "" : "text-muted-foreground")}>
          {current?.label ?? placeholder}
        </span>
        <svg
          aria-hidden="true"
          viewBox="0 0 20 20"
          fill="currentColor"
          className={cn(
            "size-4 shrink-0 text-muted-foreground motion-safe:transition-transform motion-safe:duration-150",
            open ? "rotate-180" : "",
          )}
        >
          <path d="M5.4 7 10 11.6 14.6 7 16 8.4l-6 6-6-6z" />
        </svg>
      </button>
      <AnimatePresence>
        {open ? (
          <motion.ul
            id={`${id}-list`}
            role="listbox"
            aria-label={ariaLabel}
            aria-labelledby={ariaLabelledBy}
            // Reduced motion keeps the fade and drops the growth from the trigger.
            initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.96, y: reduceMotion ? 0 : -4 }}
            animate={{ opacity: 1, scale: 1, y: 0, transition: OPEN }}
            exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.98, transition: CLOSE }}
            // A press on the list must not take focus off the trigger, which owns the keyboard.
            onMouseDown={(event) => event.preventDefault()}
            className="absolute inset-x-0 top-full z-10 mt-1 max-h-60 origin-top overflow-y-auto rounded-lg border border-border bg-card p-1 shadow-md"
          >
            {options.map((option, index) => {
              const chosen = index === selectedIndex;
              return (
                <motion.li
                  key={option.value}
                  id={optionId(index)}
                  role="option"
                  aria-selected={chosen}
                  aria-disabled={option.disabled || undefined}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ ...OPEN, delay: reduceMotion ? 0 : Math.min(index, 6) * OPTION_STAGGER }}
                  onPointerMove={() => {
                    if (!option.disabled && active !== index) setActive(index);
                  }}
                  onClick={() => choose(index)}
                  className={cn(
                    "flex min-h-11 cursor-pointer items-center gap-2 rounded-md px-2 text-foreground sm:min-h-9",
                    index === active ? "bg-muted" : "",
                    chosen ? "font-medium" : "",
                    option.disabled ? "cursor-not-allowed opacity-50" : "",
                  )}
                >
                  {option.icon}
                  <span className="min-w-0 flex-1 truncate">{option.label}</span>
                  {chosen ? (
                    <svg aria-hidden="true" viewBox="0 0 20 20" fill="currentColor" className="size-4 shrink-0">
                      <path d="M7.6 13.2 4.4 10 3 11.4 7.6 16 17 6.6 15.6 5.2z" />
                    </svg>
                  ) : null}
                </motion.li>
              );
            })}
          </motion.ul>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
